// ============================================================
// TOP OF App.js - FIXED IMPORTS
// ============================================================
import React, { useState, useEffect, useRef, useCallback, useMemo } from "react";
import { createPortal } from "react-dom";
import { supabase } from "./supabaseClient";
// NOTE: tesseract.js (~10MB incl. wasm/OCR language model) is intentionally
// NOT imported here. It used to be a static top-level import, which meant
// every single app load downloaded and parsed the full OCR engine even
// though it's only used deep inside the "scan a PDF with no text layer"
// fallback path (see ocrPdfToText below). That was a major contributor to
// "sometimes takes a while before it opens." It's now loaded on demand via
// dynamic import() right where it's actually used.

// ============================================================
// EARLY FONT LOAD (module scope - runs the instant this file is
// evaluated, before App() even mounts). The Pacifico splash-screen
// wordmark previously had its <link> injected inside a useEffect,
// which only fires AFTER React's first paint. That meant the
// font-display:block "hide text briefly" window was already
// expired (or close to it) by the time the download even started,
// so the fallback font would render first and then visibly swap to
// Pacifico a moment later - the "2 fonts" flash. Starting the fetch
// here, at parse time, gives it a multi-hundred-ms head start before
// the splash screen is even painted, so by the time it's on screen
// Pacifico is either already loaded or well within its block window.
if (typeof document !== "undefined" && !document.getElementById("ascend-pacifico-font")) {
  const preload = document.createElement("link");
  preload.rel = "preload";
  preload.as = "style";
  preload.href = "https://fonts.googleapis.com/css2?family=Pacifico&display=block";
  document.head.appendChild(preload);

  const scriptLink = document.createElement("link");
  scriptLink.id = "ascend-pacifico-font";
  scriptLink.rel = "stylesheet";
  scriptLink.href = "https://fonts.googleapis.com/css2?family=Pacifico&display=block";
  document.head.appendChild(scriptLink);

  // The preload above gives Pacifico a head start, but on a slower
  // connection (seen mainly on laptop/desktop first loads) the browser's
  // 3s font-display:block window can still run out before the woff2
  // finishes downloading - so the fallback script font (Brush Script MT /
  // Segoe Script / cursive) paints for a moment and then visibly swaps to
  // Pacifico once it lands. To kill that flash entirely, the wordmark text
  // itself (.brand-word-hero) starts invisible via CSS and only becomes
  // visible once we've confirmed Pacifico is actually loaded, using the
  // Font Loading API. A short safety timeout guarantees it becomes visible
  // regardless (e.g. offline, or a browser without document.fonts), so the
  // logo can never get stuck hidden.
  const revealWordmark = () => {
    if (document.documentElement) document.documentElement.classList.add("ascend-pacifico-ready");
  };
  try {
    if (document.fonts && document.fonts.load) {
      document.fonts.load('400 40px Pacifico').then(revealWordmark).catch(revealWordmark);
    } else {
      revealWordmark();
    }
  } catch {
    revealWordmark();
  }
  setTimeout(revealWordmark, 700);
}

// ============================================================
// LISTEN (PODCAST) VOICE HELPERS - module scope, shared by every
// TopicView instance. The Web Speech API's getVoices() list is
// populated asynchronously in most browsers (fires "voiceschanged"
// once, some time after page load), so this caches the list once
// it's ready instead of every TopicView re-querying it. Gender
// isn't a real property the API gives us reliably across browsers,
// so voices are matched by name against known male/female voice
// names shipped by Chrome, Edge, and Safari/iOS, with pitch as a
// fallback differentiator so the two options always sound distinct
// even on a device with only one or two installed voices.
const ASCEND_FEMALE_VOICE_HINTS = ["female", "zira", "samantha", "victoria", "susan", "karen", "moira", "tessa", "fiona", "google us english", "google uk english female", "aria", "jenny", "sonia", "libby", "hazel", "salli", "joanna", "amy"];
const ASCEND_MALE_VOICE_HINTS = ["male", "david", "mark", "daniel", "alex", "fred", "google uk english male", "guy", "ryan", "tom", "matthew", "brian", "arthur"];
let ascendVoicesCache = null;
function ascendGetVoices() {
  return new Promise((resolve) => {
    if (!("speechSynthesis" in window)) { resolve([]); return; }
    const existing = window.speechSynthesis.getVoices();
    if (existing && existing.length) { ascendVoicesCache = existing; resolve(existing); return; }
    if (ascendVoicesCache) { resolve(ascendVoicesCache); return; }
    const onChange = () => {
      const v = window.speechSynthesis.getVoices();
      if (v && v.length) {
        ascendVoicesCache = v;
        window.speechSynthesis.removeEventListener("voiceschanged", onChange);
        resolve(v);
      }
    };
    window.speechSynthesis.addEventListener("voiceschanged", onChange);
    // Safety timeout - some browsers never fire voiceschanged if the list
    // genuinely stays empty (e.g. headless/embedded webviews).
    setTimeout(() => resolve(window.speechSynthesis.getVoices() || []), 1200);
  });
}
async function ascendPickVoice(gender) {
  const voices = await ascendGetVoices();
  if (!voices.length) return null;
  const englishVoices = voices.filter((v) => /^en/i.test(v.lang)) ;
  const pool = englishVoices.length ? englishVoices : voices;
  const hints = gender === "female" ? ASCEND_FEMALE_VOICE_HINTS : ASCEND_MALE_VOICE_HINTS;
  const byName = pool.find((v) => hints.some((h) => v.name.toLowerCase().includes(h)));
  if (byName) return byName;
  // No name match - fall back to a deterministic split of whatever's
  // available so male/female still pick two different installed voices.
  if (pool.length > 1) return gender === "female" ? pool[0] : pool[1];
  return pool[0] || null;
}

// Dead code removed: extractTextFromImage() was never called anywhere in
// the app (already flagged eslint no-unused-vars) but was still pulling in
// Tesseract at module scope, which meant it was bundled and paid for on
// every load despite doing nothing. Deleted entirely rather than kept
// dormant. The app's one real OCR path is ocrPdfToText() further down,
// which now loads Tesseract lazily via dynamic import().
// ============================================================
// FIX: Suppress browser extension errors (Grammarly, etc.)
// ============================================================
if (typeof window !== 'undefined') {
  // Catch and suppress extension communication errors
  window.addEventListener('error', (e) => {
    if (e.message && e.message.includes('message channel closed')) {
      e.preventDefault();
      e.stopPropagation();
      return true;
    }
  });
  
  // Catch unhandled promise rejections from extensions
  window.addEventListener('unhandledrejection', (e) => {
    if (e.reason && e.reason.message && e.reason.message.includes('message channel closed')) {
      e.preventDefault();
      e.stopPropagation();
      return true;
    }
  });
}

