/* ============================================================
   AVATAR SYSTEM
   ------------------------------------------------------------
   Instead of 36 separate hand-drawn SVGs (one per face/hair/skin
   combination), each part is ONE shape drawn once, and skin tone /
   hair colour are passed in as a fill colour parameter. This gets
   the same amount of real choice (3 faces x 3 hair x 3 skin x 3
   hair colours x 2 extras = 162 combinations) from just 6 drawn
   shapes, so adding a new skin tone or hair colour later is a
   one-line hex code, not a new drawing.
   ============================================================ */
const AVATAR_SKIN_TONES = ["#F5D0B0", "#C68642", "#6B4226"];
const AVATAR_HAIR_COLORS = ["#1B1210", "#6B4226", "#D9A441"];

// Face shape is locked to one standard circle - no picker section, no
// decision for the student to make here.
const AVATAR_FACES = {
  round: { label: "Round", shape: (fill) => <ellipse cx="50" cy="54" rx="32" ry="34" fill={fill} /> },
};

// gender is now a HARD filter (student picks Male or Female once, up
// front) rather than a sort hint - each list only shows that gender's 4
// styles, matching what was asked for explicitly here.
// Helper: derive a highlight tint and shadow tint from a base hair colour, so
// every style gets volume instead of reading as a flat silhouette. Uses the
// same lightness math as the rest of the app's colour helpers.
const hairShade = (hex, pct) => {
  try {
    const h = String(hex).replace("#", "");
    const n = parseInt(h.length === 3 ? h.split("").map(c => c + c).join("") : h, 16);
    let r = (n >> 16) + Math.round((pct / 100) * 255);
    let g = ((n >> 8) & 0x00ff) + Math.round((pct / 100) * 255);
    let b = (n & 0x0000ff) + Math.round((pct / 100) * 255);
    r = Math.max(0, Math.min(255, r)); g = Math.max(0, Math.min(255, g)); b = Math.max(0, Math.min(255, b));
    return "#" + (0x1000000 + r * 0x10000 + g * 0x100 + b).toString(16).slice(1);
  } catch { return hex; }
};

