/* ===================== LECTURE SLIDES (Google Drive) =====================
   Slides live in one shared Drive folder in a dedicated ASCEND Google
   account. Each file is named "<courseId>_<topicIndex>_description.ext" -
   that's the only linking step; matching is fully automatic below.
   The folder is shared "Anyone with the link -> Viewer" and the API key is
   restricted (Drive API only, HTTP referrer locked to the deployed domain),
   so this is safe to ship in client code. */

const DRIVE_API_KEY = "AIzaSyBtnnk4Zd8-l6incfE1JQtbkqMJNbjtuk8";
const DRIVE_FOLDER_ID = "1jQlxuYFqrx4U4HGhaERrDKUFgtiWiTeN";

let _driveSlidesCache = null;
let _driveSlidesPromise = null;
const DRIVE_CACHE_MS = 30 * 60 * 1000; // refetch at most every 30 min
let _driveSlidesFetchedAt = 0;

async function fetchDriveSlideFiles() {
  const now = Date.now();
  if (_driveSlidesCache && (now - _driveSlidesFetchedAt) < DRIVE_CACHE_MS) return _driveSlidesCache;
  if (_driveSlidesPromise) return _driveSlidesPromise;

  const fields = encodeURIComponent("nextPageToken, files(id,name,thumbnailLink,webViewLink,mimeType,size)");
  const q = encodeURIComponent(`'${DRIVE_FOLDER_ID}' in parents and trashed = false`);

  // Google's Drive API caps how many files it actually returns per page,
  // regardless of the pageSize we ask for (in practice this can be well
  // under 1000, e.g. ~57 was the real cutoff seen here). We MUST follow
  // nextPageToken until it stops appearing, or files silently go missing
  // with no error - it just looks like "some slides never loaded."
  async function fetchAllPages() {
    let allFiles = [];
    let pageToken = "";
    let guard = 0; // safety net against an infinite loop if Google ever misbehaves
    do {
      const url = `https://www.googleapis.com/drive/v3/files?q=${q}&fields=${fields}&pageSize=1000&key=${DRIVE_API_KEY}` +
        (pageToken ? `&pageToken=${pageToken}` : "");
      const res = await fetch(url);
      const data = await res.json();
      if (data && data.error) {
        console.error("Drive slides API error:", data.error.code, data.error.message, data.error);
        break;
      }
      if (Array.isArray(data.files)) allFiles = allFiles.concat(data.files);
      pageToken = data.nextPageToken || "";
      guard++;
    } while (pageToken && guard < 50); // 50 pages = 50,000 files, way more than enough headroom
    return allFiles;
  }

  _driveSlidesPromise = fetchAllPages()
    .then((allFiles) => {
      _driveSlidesCache = allFiles;
      _driveSlidesFetchedAt = Date.now();
      _driveSlidesPromise = null;
      console.log("Drive slides loaded:", _driveSlidesCache.length, "files");
      logUnmatchedDriveFiles(_driveSlidesCache);
      return _driveSlidesCache;
    })
    .catch((e) => {
      console.error("Drive slides fetch failed:", e);
      _driveSlidesPromise = null;
      return _driveSlidesCache || [];
    });
  return _driveSlidesPromise;
}

// Normalizes a raw Drive filename before prefix matching. Handles two real
// issues seen in the wild: (1) a stray leading/trailing space someone typed
// when renaming a file in Drive (" psy_3_..." never starts with "psy_3_" as
// far as .startsWith() is concerned), and (2) Drive's own "Copy of " prefix
// added automatically when a file gets duplicated ("Copy of ana_3_...").
function normalizeDriveFileName(name) {
  let n = (name || "").trim();
  // Strip one or more "Copy of " / "copy of " prefixes (Drive can stack these
  // if a file gets duplicated more than once), then re-trim.
  while (/^copy of\s+/i.test(n)) {
    n = n.replace(/^copy of\s+/i, "").trim();
  }
  return n;
}

// Diagnostic: after every Drive fetch, log any filename that doesn't start
// with a "<courseId>_<topicIndex>_" prefix matching a CURRENT topic. This is
// what catches the "some topics don't show slides" bug - usually caused by
// TOPICS array indices shifting (e.g. inserting a topic in the middle) while
// the Drive filenames still reference the old index.
function logUnmatchedDriveFiles(files) {
  if (!Array.isArray(files) || files.length === 0) return;

  // Build the full set of valid prefixes from the current TOPICS data.
  const validPrefixes = new Set();
  Object.keys(TOPICS).forEach((courseId) => {
    TOPICS[courseId].forEach((_, topicIndex) => {
      validPrefixes.add(`${courseId}_${topicIndex}_`.toLowerCase());
    });
  });

  const unmatched = files.filter((f) => {
    const name = normalizeDriveFileName(f.name).toLowerCase();
    // does it start with SOME "<id>_<num>_" pattern at all?
    const m = name.match(/^([a-z0-9]+)_(\d+)_/i);
    if (!m) return true; // doesn't even follow the naming convention
    const prefix = `${m[1]}_${m[2]}_`.toLowerCase();
    return !validPrefixes.has(prefix);
  });

  if (unmatched.length > 0) {
    console.warn(
      `[Drive slides] ${unmatched.length} file(s) don't match any current topic index ` +
      `(likely a stale filename after topics were reordered/inserted, or a stray ` +
      `leading space / "Copy of " in the Drive filename):`,
      unmatched.map((f) => f.name)
    );
  }
}

// Matches files named "<courseId>_<topicIndex>_...ext" (case-insensitive).
// Also matches an EXACT duplicate index collision on purpose: if two files
// both legitimately target "lab_1_", both should show up as slide options
// for that topic (e.g. "Part 1" and "Part 2" decks for the same lecture).
function slidesForTopic(files, courseId, topicIndex) {
  const prefix = `${courseId}_${topicIndex}_`.toLowerCase();
  return (files || []).filter((f) => {
    const name = normalizeDriveFileName(f.name).toLowerCase();
    return name.startsWith(prefix);
  });
}

function LectureSlides({ courseId, topicIndex }) {
  const [files, setFiles] = useState(null);

  useEffect(() => {
    let alive = true;
    fetchDriveSlideFiles().then((all) => { if (alive) setFiles(all); });
    return () => { alive = false; };
  }, []);

  if (files === null) return null; // still loading - render nothing rather than a flash
  const matches = slidesForTopic(files, courseId, topicIndex);
  if (matches.length === 0) return null;

  const cleanName = (name) =>
    normalizeDriveFileName(name).replace(/^[a-z0-9]+_\d+_/i, "").replace(/\.[^.]+$/, "").replace(/[-_]+/g, " ").trim();

  // If a PDF export lives alongside the original file (same "<courseId>_
  // <topicIndex>_" prefix, uploaded separately), use it as the preview
  // fallback for any file too large for Google's Slides converter. PDFs
  // stream directly through Drive with no conversion step, so there's no
  // 100MB cap on them the way there is on PPTX preview.
  const pdfFallback = matches.find((m) => m.mimeType === "application/pdf") || null;

  return (
    <div className="slide-links">
      {matches
        .filter((f) => f !== pdfFallback || matches.length === 1) // don't double-list the PDF as its own fallback unless it's the only file
        .map((f) => <SlideLinkChip key={f.id} f={f} cleanName={cleanName} pdfFallback={f.mimeType === "application/pdf" ? null : pdfFallback} />)}
    </div>
  );
}

// Google's own Slides/Docs converter refuses to preview any file over
// exactly 100MB (104,857,600 bytes) - this is a hard Google-side limit, not
// something we can work around client-side. Clicking "View" on a file above
// this size will always throw a FILE_TOO_LARGE error, no matter what URL we
// point it at. So: for files at/above this size, we just don't offer a
// preview link at all - only Download, which has no such cap.
const DRIVE_PREVIEW_MAX_BYTES = 100 * 1024 * 1024;

function formatBytes(bytes) {
  const n = Number(bytes);
  if (!n) return "";
  if (n >= 1024 * 1024) return `${(n / (1024 * 1024)).toFixed(1)} MB`;
  return `${Math.round(n / 1024)} KB`;
}

// Simple link-chip - no thumbnail, so it can't break on Drive's inconsistent
// preview generation. Just a slide icon + filename that opens the deck.
// Div wrapper (not <a>) so the "View" and "Download" links can sit as
// siblings instead of illegally nesting an <a> inside an <a>.
function SlideLinkChip({ f, cleanName, pdfFallback }) {
  const size = Number(f.size) || 0;
  const tooLargeToPreview = size >= DRIVE_PREVIEW_MAX_BYTES;
  const previewFile = tooLargeToPreview && pdfFallback ? pdfFallback : f;
  const previewBlocked = tooLargeToPreview && !pdfFallback;

  return (
    <div className="slide-chip">
      <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        <path d="M12 2L2 7l10 5 10-5-10-5z" />
        <path d="M2 17l10 5 10-5" />
        <path d="M2 12l10 5 10-5" />
      </svg>
      {previewBlocked ? (
        // Not clickable to a preview - Google Slides hard-caps conversion at
        // 100MB, so a "View" link here would just error out every time, and
        // there's no PDF fallback uploaded for this one yet.
        <span
          className="slide-chip-name"
          title={`${formatBytes(size)} - too large for Google's preview (100MB limit). Upload a PDF export alongside it to enable View, or use Download.`}
          style={{ color: "inherit", opacity: 0.85 }}
        >
          {cleanName(f.name)} <span style={{ opacity: 0.6, fontWeight: 400 }}>({formatBytes(size)})</span>
        </span>
      ) : (
        <a
          href={previewFile.webViewLink}
          target="_blank"
          rel="noopener noreferrer"
          className="slide-chip-name"
          style={{ color: "inherit", textDecoration: "none" }}
          title={tooLargeToPreview ? `Previewing PDF export (${formatBytes(size)} original is too large for Slides preview)` : undefined}
        >
          {cleanName(f.name)}{tooLargeToPreview ? <span style={{ opacity: 0.6, fontWeight: 400 }}> (PDF preview)</span> : null}
        </a>
      )}
      <a href={`https://www.googleapis.com/drive/v3/files/${f.id}?alt=media&key=${DRIVE_API_KEY}`} className="slide-chip-dl">
        Download
      </a>
    </div>
  );
}

/* ===================== SLIDES TAB =====================
   A dedicated top-level view: pick a course -> see every topic with its own
   slide chips underneath, in one place. Deliberately kept separate from
   TopicView's lesson notes so slides never sit inline with written content -
   this is the only place slides live in the app now. */
function slideCountForTopic(files, courseId, topicIndex) {
  return slidesForTopic(files, courseId, topicIndex).length;
}

// One course's slide "folder": every matching file in syllabus (topic) order,
// de-duplicated by Drive id, with the PDF export attached as a fallback to
// its parent deck instead of being counted as a separate file. Shared by the
// course picker's counts and the course screen's list so the two can never
// disagree about how many slides a course has.
function buildSlideDeck(files, courseId) {
  const deck = [];
  const seen = {};
  (TOPICS[courseId] || []).forEach((_, i) => {
    const matches = slidesForTopic(files, courseId, i);
    if (!matches.length) return;
    const pdfFallback = matches.find((m) => m.mimeType === "application/pdf") || null;
    matches
      .filter((f) => f !== pdfFallback || matches.length === 1)
      .forEach((f) => {
        if (seen[f.id]) return;
        seen[f.id] = true;
        deck.push({ f: f, pdf: f.mimeType === "application/pdf" ? null : pdfFallback });
      });
  });
  return deck;
}

function SlidesView({ app }) {
  const [files, setFiles] = useState(null);
  const [courseId, setCourseId] = useState(null); // null = course picker; set = topic list for that course

  useEffect(() => {
    let alive = true;
    fetchDriveSlideFiles().then((all) => { if (alive) setFiles(all); });
    return () => { alive = false; };
  }, []);

  const loading = files === null;

  // Course picker screen
  if (!courseId) {
    // Only count what this student can actually open: the courses for their
    // own level and semester, using the same de-duplicated deck the course
    // screen shows. (The Drive folder holds every level's files, so the raw
    // folder size would overstate what they have.)
    const myCourses = visibleCoursesFor(app.progress);
    const countsByCourse = {};
    let totalForYou = 0;
    if (!loading) {
      myCourses.forEach((c) => {
        countsByCourse[c.id] = buildSlideDeck(files, c.id).length;
        totalForYou += countsByCourse[c.id];
      });
    }
    return (
      <div className="view">
        <div className="eyebrow">Lecture Slides</div>
        <h1 style={{ fontSize: "clamp(22px,4vw,28px)", margin: "6px 0 4px" }}>Pick a course</h1>
        <div style={{ color: "var(--text-3)", fontSize: 13.5, marginBottom: 16 }}>
          {loading ? "Loading slide library..." : `${totalForYou} slide file${totalForYou === 1 ? "" : "s"} for your level and semester`}
        </div>
        <div style={{ display: "grid", gap: 10 }}>
          {myCourses.map((c) => {
            const count = loading ? null : countsByCourse[c.id];
            return (
              <button
                key={c.id}
                className="card hover"
                style={{ textAlign: "left", display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10 }}
                onClick={() => setCourseId(c.id)}
              >
                <div>
                  <div style={{ fontWeight: 650, fontSize: 15.5 }}>{c.name}</div>
                  <div style={{ color: "var(--text-3)", fontSize: 12.5, marginTop: 2 }} className="mono">{c.code}</div>
                </div>
                <div style={{ fontSize: 12.5, color: "var(--text-3)", flexShrink: 0 }}>
                  {loading ? "…" : `${count} slide file${count === 1 ? "" : "s"}`}
                </div>
              </button>
            );
          })}
        </div>
      </div>
    );
  }

  // Course "folder" screen: every slide in the course flattened into one list,
  // ordered by ASCEND topic (syllabus) order. No per-topic grouping and no
  // "No slides yet" rows - just the decks that exist, like a Drive folder.
  const course = COURSES.find((c) => c.id === courseId);
  const topics = TOPICS[courseId] || [];

  const cleanName = (name) =>
    normalizeDriveFileName(name).replace(/^[a-z0-9]+_\d+_/i, "").replace(/\.[^.]+$/, "").replace(/[-_]+/g, " ").trim();

  const deck = loading ? [] : buildSlideDeck(files, courseId);

  return (
    <div className="view">
      <button className="back" onClick={() => setCourseId(null)}>
        <Ic.chevR p={15} style={{ transform: "rotate(180deg)" }} /> All courses
      </button>
      <div className="eyebrow" style={{ marginTop: 10 }}>Lecture Slides · {course.code}</div>
      <h1 style={{ fontSize: "clamp(22px,4vw,28px)", margin: "6px 0 4px" }}>{course.name}</h1>
      <div style={{ color: "var(--text-3)", fontSize: 13, marginBottom: 14 }}>
        {loading ? "Loading slide library..." : (deck.length + " slide file" + (deck.length === 1 ? "" : "s") + (deck.length ? " · in syllabus order" : ""))}
      </div>

      {loading ? (
        <div style={{ color: "var(--text-3)", fontSize: 13.5 }}>Loading slide library...</div>
      ) : deck.length === 0 ? (
        <div className="card" style={{ color: "var(--text-3)", fontSize: 13.5, padding: 16 }}>
          No slides uploaded for this course yet. Check back soon.
        </div>
      ) : (
        <div className="card" style={{ padding: 12 }}>
          <div className="slide-links">
            {deck.map((d) => (
              <SlideLinkChip key={d.f.id} f={d.f} cleanName={cleanName} pdfFallback={d.pdf} />
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

/* ============================================================
   CONTENT DATA
   ------------------------------------------------------------
   All lesson content (previously ~29,700 lines of T_* constants and
   the CONTENT registry, inlined directly here) has been moved to
   ./contentData.js to isolate app logic from lesson data. Behavior
   is unchanged - CONTENT is still imported eagerly, just from its
   own module now. See the header comment in contentData.js for the
   plan to make this a real lazy per-course load.
   ============================================================ */
import { CONTENT } from "./contentData";
import AtlasView from "./AtlasView";
import { DIAGRAMS } from "./diagrams";


const contentFor = (cid, tid) => CONTENT[`${cid}:${tid}`] || null;

// A course is "ready" the moment at least one of its topics has authored
// CONTENT. Courses with a non-empty TOPICS list but zero CONTENT entries
// (e.g. cap/csf/bc1/... right after skeleton deploy, before topics are
// filled in) are "coming soon" - CoursesView/CourseView should check this
// and render the placeholder instead of an empty topic list.
const isCourseReady = (cid) => {
  const topics = TOPICS[cid] || [];
  if (!topics.length) return false;
  return topics.some((_, i) => !!contentFor(cid, i));
};
const courseReadyCount = (cid) => (TOPICS[cid] || []).filter((_, i) => !!contentFor(cid, i)).length;

// ===================== COHORT / LEVEL MODEL =====================
// A student's level is COMPUTED from when they entered (entryYear), never
// stored directly - this is what makes promotion automatic and generational
// (see planning discussion): nobody's account needs to be touched by hand
// for a cohort to move from Level 100 to Level 200 next year.
//
// ACADEMIC_CALENDAR holds one small, yearly-maintained entry per academic
// year. `rollover` is the real "students depart" date that ends that
// cohort's final semester of the year - promotion fires on that date, not
// on KNUST's official year-start or next semester's teaching-start date
// (confirmed: this cohort's own Sem 2 vacation date, not a guess).
const ACADEMIC_CALENDAR = {
  // Level 100 Sem 2 cohort's actual vacation date this year - hardcoded
  // because it's the real, confirmed date, not a provisional one.
  2025: { rollover: "2026-09-04" },
  // 2026/2027 KNUST calendar - Sem 2 "Students Depart" is published as
  // provisional (26 Jun 2027); update this once the real date is confirmed
  // closer to the time, same as 2025 was hardcoded above once it was known.
  2026: { rollover: "2027-06-26", provisional: true },
};
// Ceiling for the MLS program - nobody's computed level should climb past
// this even if the calendar keeps rolling forward.
const MAX_LEVEL = 400;

// entryYear = the academic year (e.g. 2025) a student entered Level 100 in.
// Returns their current level today, capped at MAX_LEVEL. `overrideLevel`
// (from the manual-override field, e.g. for repeats/deferrals) always wins
// when set, per the edge-case plan.
function computeCurrentLevel(entryYear, today = new Date(), overrideLevel = null) {
  if (overrideLevel != null) return overrideLevel;
  if (!entryYear) return null;
  let level = 100;
  let year = entryYear;
  while (ACADEMIC_CALENDAR[year] && today >= new Date(ACADEMIC_CALENDAR[year].rollover + "T00:00:00")) {
    level += 100;
    year += 1;
    if (level >= MAX_LEVEL) { level = MAX_LEVEL; break; }
  }
  return level;
}

// Access = entryLevel..currentLevel inclusive (a student keeps everything
// they've already passed through), never just the current level alone.
function accessibleLevels(entryYear, today = new Date(), overrideLevel = null) {
  const current = computeCurrentLevel(entryYear, today, overrideLevel);
  const levels = [];
  for (let lv = 100; lv <= current; lv += 100) levels.push(lv);
  return levels;
}

// All courses a student can currently open: every level they've passed
// through, both semesters (semester itself is just a display filter/tab,
// not an access gate - a student can review last semester's material too).
const coursesForStudent = (entryYear, today = new Date(), overrideLevel = null) => {
  const levels = accessibleLevels(entryYear, today, overrideLevel);
  return COURSES.filter((c) => levels.includes(c.level));
};

// Every (level, semester) combo that actually has courses defined, in
// chronological/progression order. Extend this the moment a new combo gets
// added to COURSES (e.g. once Level 200 Sem 2 is authored) - everything
// below reads from this list, nothing else needs to change.
const LEVEL_SEMESTER_CONTENT = [
  { level: 100, semester: 1 },
  { level: 100, semester: 2 },
  { level: 200, semester: 1 },
];
const levelSemesterKey = (lv, sem) => lv * 10 + sem;

// A student picks their real level/semester at signup, which may be AHEAD
// of what's actually been built (e.g. Level 200 Sem 2, or Level 300/400 -
// none of which have courses yet). Rather than showing them nothing, this
// clamps down to the most advanced combo that actually exists - "if you
// picked further than we've built, here's as far as we've got." Returns the
// exact combo picked if it exists.
function effectiveLevelSemester(level, semester) {
  const wanted = levelSemesterKey(level || 100, semester || 1);
  let best = LEVEL_SEMESTER_CONTENT[0];
  for (const c of LEVEL_SEMESTER_CONTENT) {
    if (levelSemesterKey(c.level, c.semester) <= wanted) best = c;
  }
  return best;
}

// Single shared source of truth for "which courses should this student see
// right now" - CoursesView's own gating logic, factored out so every OTHER
// view that lists/pickers courses (Slides, PASSCO/Papers, the AI tutor,
// Forum, etc.) applies the exact same level+semester rule instead of each
// independently showing the unfiltered COURSES array. Anything that lists
// courses for a logged-in student should call this, not COURSES directly -
// that's what "adapts to level/semester everywhere" actually means in code.
function visibleCoursesFor(progress) {
  if (!progress || !progress.level) return COURSES;
  const eff = effectiveLevelSemester(progress.level, progress.semester || 1);
  return COURSES.filter((c) => (c.level || 100) === eff.level && (c.semester || 1) === eff.semester);
}

/* ===================== LIFETIME STREAK / HALL OF FAME =====================
   Suggested design (implemented below):
   - `streak` (existing field) is the CURRENT semester's streak - unchanged.
   - `lifetimeStreak` is a running total: every time a semester closes, that
     semester's final streak is ADDED to lifetimeStreak, then `streak` resets
     to 0 for the new semester. Lifetime never goes down - it's the "career
     total" the way Duolingo's total XP never resets even though daily/weekly
     numbers do.
   - The first 3 students by that semester's final streak get locked into a
     shared Hall of Fame record for that semester, so the achievement is
     preserved even though the leaderboard itself moves on to the new term.

   Both boundaries are now real, confirmed dates from KNUST's 2026/2027
   Provisional Academic Calendar:
   - Sem1 -> Sem2 (this year): "Students Depart" Sat, Feb 13, 2027.
   - Sem2 -> next year's Sem1: "Students Depart" Sat, Jun 26, 2027 - already
     covered by ACADEMIC_CALENDAR's 2026 entry above, so it's not repeated
     here (that one drives the level-100->200-style yearly rollover too).
   This needs one line added to SEMESTER_BOUNDARIES every year once KNUST
   publishes that year's Sem1->Sem2 "Students Depart" date - same yearly
   upkeep ACADEMIC_CALENDAR already requires. */
const SEMESTER_BOUNDARIES = [
  // First Semester 2026/2027 "Students Depart" (confirmed, KNUST calendar
  // item 1.21) -> Second Semester begins. `forYear: 2026` ties this to the
  // 2026/2027 academic-year window specifically (the window ACADEMIC_CALENDAR
  // resolves as yearKey === 2026), so it stops applying once the next annual
  // rollover (Jun 26, 2027) moves yearKey to 2027 - it won't wrongly persist
  // into next year's Sem1.
  { date: "2027-02-13", forYear: 2026, key: "S2" },
];

// A stable id for "the semester currently in progress", changes exactly on
// the dates configured above. Used purely to detect "a boundary has been
// crossed since I last checked", not to compute level.
function semesterKeyFor(today = new Date()) {
  const t = today.getTime();
  const years = Object.keys(ACADEMIC_CALENDAR).map(Number).sort((a, b) => a - b);
  let yearKey = years.length ? years[0] : today.getFullYear();
  for (const y of years) {
    if (t >= new Date(ACADEMIC_CALENDAR[y].rollover + "T00:00:00").getTime()) yearKey = y + 1;
  }
  // Only a boundary tagged for THIS academic-year window can apply, so a
  // mid-year marker never bleeds into the following year once yearKey moves
  // past it (see SEMESTER_BOUNDARIES comment above).
  const extra = SEMESTER_BOUNDARIES
    .filter((b) => b.forYear === yearKey && t >= new Date(b.date + "T00:00:00").getTime())
    .sort((a, b) => new Date(b.date) - new Date(a.date))[0];
  return extra ? `${yearKey}:${extra.key}` : `${yearKey}`;
}

// Which semester (1 or 2) is actually running right now, per the same
// SEMESTER_BOUNDARIES data semesterKeyFor uses. Not currently used for
// course gating (CoursesView uses what the student picked at signup
// instead - see effectiveLevelSemester), kept as a utility for the
// lifetime-streak/Hall-of-Fame semester-close logic and any future move to
// auto-advancing a student's semester off the calendar instead of asking.
function currentSemesterNumber(today = new Date()) {
  return semesterKeyFor(today).endsWith(":S2") ? 2 : 1;
}

// Pure function: given a progress object, decides whether a semester
// boundary was crossed since progress.lastSemesterKey was last recorded.
// Returns the SAME object (no-op) if nothing changed, or a new object with
// streak banked into lifetimeStreak and reset. The caller is responsible for
// persisting the result and (if `closed` is set) publishing it to the Hall
// of Fame board - see closeSemesterAndPersist in the App component.
function closeSemesterIfNeeded(progress, today = new Date()) {
  const key = semesterKeyFor(today);
  if (!progress.lastSemesterKey) {
    // First time this field is ever populated for this student - just start
    // tracking from here, don't treat "never set before" as a closure.
    return { ...progress, lastSemesterKey: key, closed: null };
  }
  if (progress.lastSemesterKey === key) return { ...progress, closed: null };
  const closedKey = progress.lastSemesterKey;
  const closedStreak = progress.streak || 0;
  return {
    ...progress,
    lifetimeStreak: (progress.lifetimeStreak || 0) + closedStreak,
    streak: 0,
    lastSemesterKey: key,
    closed: { key: closedKey, streak: closedStreak },
  };
}

const hofSlug = (name) => String(name || "").toLowerCase().replace(/[^a-z0-9]/g, "");

// Publishes this student's final streak for a semester that just closed for
// them. Every student who logs in right after the boundary publishes their
// own entry (first-write-wins per student, since the key is per-student) -
// there's no central "close the semester" job to run, it happens organically
// as students open the app. Safe to call more than once; last value wins.
async function publishHallOfFameEntry(semesterKey, name, streak) {
  if (!semesterKey || !name || !streak) return;
  try { await store.setShared(`ascend_hof:${semesterKey}:${hofSlug(name)}`, { name, streak }); } catch {}
}

// Reads back the top 3 (by streak) published for a given closed semester.
async function topStreaksForSemester(semesterKey, n = 3) {
  try {
    const keys = await store.listShared(`ascend_hof:${semesterKey}:`);
    const rows = [];
    for (const k of keys) {
      const v = await store.get(k, true);
      if (v && v.name && typeof v.streak === "number") rows.push(v);
    }
    return rows.sort((a, b) => b.streak - a.streak).slice(0, n);
  } catch { return []; }
}



// Builds a grounding block listing the real syllabus topics (and a sample of
// key concepts) for a course, so every AI question generator - Practice set
// (AI) and Generate similar alike - stays inside the actual KNUST curriculum
// instead of drifting into generic/external content.
const curriculumContextFor = (cid, topicName) => {
  const topics = TOPICS[cid] || [];
  if (!topics.length) return "";

  // When a specific topic is chosen, lock the grounding to ONLY that topic.
  // Listing the other syllabus topics (even just for "context") is what was
  // inviting drift - the AI would occasionally borrow content from a
  // neighboring topic. So in single-topic mode we omit the full topicList
  // entirely and give a hard single-topic instruction instead.
  if (topicName) {
    const idx = topics.findIndex((t) => t === topicName);
    let sample = "";
    if (idx >= 0) {
      const t = contentFor(cid, idx);
      if (t) {
        const noteText = (t.note || []).slice(0, 6).map((n) => n.q).join("; ");
        if (noteText) sample = `\nKey concepts within this topic (for grounding, not an exhaustive list):\n${noteText}`;
      }
    }
    return `CURRICULUM GROUNDING (mandatory, STRICT single-topic mode): The ONLY topic in scope is "${topicName}".${sample}\nEvery single question MUST test knowledge that falls strictly within "${topicName}" and nothing else. Do NOT include, reference, or drift into any other topic from this course's syllabus, even ones that are closely related, come right before/after it, or share overlapping concepts. Do NOT introduce concepts, terminology, or depth outside this exact topic, even if related in general biology/science.`;
  }

  const topicList = topics.join(", ");
  let sample = "";
  for (let i = 0; i < Math.min(3, topics.length); i++) {
    const t = contentFor(cid, i);
    if (t) {
      const noteText = (t.note || []).slice(0, 3).map((n) => n.q).join("; ");
      sample += `- ${t.title}: ${noteText}\n`;
    }
  }
  return `CURRICULUM GROUNDING (mandatory): This course's syllabus topics are: ${topicList}.${sample ? `\nSample key concepts from the syllabus:\n${sample}` : ""}\nEvery question MUST test knowledge that falls within these syllabus topics. Do NOT introduce concepts, terminology, or depth outside this curriculum, even if related in general biology/science.`;
};
const builtInCourse = (cid) => Object.keys(CONTENT).filter((k) => k.startsWith(cid + ":")).length;
const totalBuilt = () => Object.keys(CONTENT).length;
// Same count, but scoped to whatever's actually visible at the student's
// current level/semester - used anywhere a stat needs to adapt/sync with
// the level/semester switch instead of counting across the whole app.
const totalBuiltFor = (progress) => {
  const visibleIds = new Set(visibleCoursesFor(progress).map((c) => c.id));
  return Object.keys(CONTENT).filter((k) => visibleIds.has(k.split(":")[0])).length;
};

/* ===================== END-OF-SEMESTER EXAM TIMETABLE =====================
   PLACEHOLDER - replace date/time/venue below with the real KNUST MLS 2029
   timetable. Each entry: courseId (must match a COURSES id), date "YYYY-MM-DD",
   time "h:mm AM/PM" (start time), and optional venue. Keep entries sorted by
   date - order doesn't matter functionally (NextExamCard sorts them) but it's
   easier to eyeball this way. A short list of exam-day tips per course lives
   in EXAM_TIPS below; edit freely per course. */
const EXAM_TIMETABLE = [
  { courseId: "bch", label: "Practical", date: "2026-08-19", time: "8:00 AM", venue: "G03, G01, 101, 201" },
  { courseId: "bch", label: "Theory", date: "2026-08-20", time: "8:00 AM", venue: "Online (IT Labs)" },
  { courseId: "phy", label: "Practical", date: "2026-08-25", time: "8:30 AM", venue: "201, 301, 401" },
  { courseId: "bio", date: "2026-08-26", time: "12:00 PM", venue: "201, 301, 401" },
  { courseId: "phy", label: "Theory", date: "2026-08-28", time: "12:00 PM", venue: "201, 301, 401" },
  { courseId: "psy", date: "2026-08-31", time: "8:30 AM", venue: "G01, 101, 201" },
  { courseId: "com", date: "2026-09-01", time: "8:30 AM", venue: "Online (IT Labs)" },
  { courseId: "lab", date: "2026-09-02", time: "8:30 AM", venue: "G01, 101, 201" },
  { courseId: "ana", label: "Practicals", date: "2026-09-03", time: "8:30 AM", venue: "201, 301, 401" },
  { courseId: "ana", label: "Theory", date: "2026-09-04", time: "8:30 AM", venue: "201, 301, 401" },
];

const EXAM_TIPS = {
  ana: "You've put in the work - now walk in and take it. Read every question twice before you answer, don't let one hard question steal your calm, and if you blank, move on and come back. Finish strong.",
  phy: "This is your paper to win. Manage your time from the first minute - don't marry a tough question, bank the easy marks first, then hunt down the rest. Trust your prep.",
  bch: "Stay locked in. Skim the whole paper first so nothing surprises you, attack what you know cold, then grind the rest. You've done the reps - now execute.",
  bio: "Go in calm and go in ready. Don't rush the first few questions just because you're nervous - settle in, find your rhythm, and let your preparation carry you through.",
  psy: "Read carefully, answer deliberately, don't second-guess yourself into a wrong answer. You know this - trust the first instinct that comes from real preparation.",
  com: "Structure first, then fill it in. Plan your answer for a beat before you write, keep it clean and organised, and watch your time so every section gets attention.",
  lab: "Precision wins this paper. Read each question fully before choosing - don't answer the question you expected instead of the one that's actually there. Stay sharp to the last minute.",
  bcp: "Practical thinking, not just memory. Picture the actual steps as you answer, don't rush the details, and finish every question - a blank answer is a guaranteed zero, a guess is a chance.",
  phyp: "Think mechanism, not just recall - picture the ions, channels, and steps as you answer. Cover the core seven topics solidly; Urinalysis is a bonus extra, so don't let it steal time from the core paper.",
};

// Returns the next not-yet-passed exam (by date, then time), or null if all
// exams in EXAM_TIMETABLE are in the past.
function nextUpcomingExam() {
  const now = new Date();
  const upcoming = EXAM_TIMETABLE
    .map((e) => ({ ...e, dt: new Date(`${e.date}T${to24h(e.time)}:00`) }))
    .filter((e) => e.dt >= now)
    .sort((a, b) => a.dt - b.dt);
  return upcoming[0] || null;
}

function to24h(t) {
  // "9:00 AM" -> "09:00", "1:30 PM" -> "13:30"
  const m = /^(\d{1,2}):(\d{2})\s*(AM|PM)$/i.exec(t.trim());
  if (!m) return "09:00";
  let [, h, min, ap] = m;
  h = parseInt(h, 10);
  if (/pm/i.test(ap) && h !== 12) h += 12;
  if (/am/i.test(ap) && h === 12) h = 0;
  return `${String(h).padStart(2, "0")}:${min}`;
}

function NextExamCard() {
  const next = nextUpcomingExam();
  if (!next) {
    // All exams in EXAM_TIMETABLE have passed.
    return (
      <div className="card card-feature" style={{ marginTop: 16, display: "flex", alignItems: "center", gap: 16, flexWrap: "wrap" }}>
        <div style={{ flexShrink: 0, width: 72, height: 72, borderRadius: 16, background: "var(--amber-dim)", display: "flex", alignItems: "center", justifyContent: "center" }}>
          <Ic.flame p={30} />
        </div>
        <div style={{ flex: 1, minWidth: 200 }}>
          <div className="eyebrow" style={{ color: "var(--amber)", marginBottom: 4 }}>Exams complete</div>
          <div style={{ fontSize: 14.5, color: "var(--text-2)", lineHeight: 1.55 }}>
            That's the last paper down. Great climb - rest up, and keep an eye out here for what's next.
          </div>
        </div>
      </div>
    );
  }

  const course = COURSES.find((c) => c.id === next.courseId);
  const msPerDay = 1000 * 60 * 60 * 24;
  const daysLeft = Math.ceil((next.dt - new Date()) / msPerDay);
  const tip = EXAM_TIPS[next.courseId];

  let dayLabel;
  if (daysLeft <= 0) dayLabel = "TODAY";
  else if (daysLeft === 1) dayLabel = "DAY";
  else dayLabel = "DAYS";

  const dateLabel = next.dt.toLocaleDateString("en-GB", { weekday: "short", day: "numeric", month: "short" });

  return (
    <div className="card card-feature" style={{ marginTop: 16, display: "flex", flexDirection: "column", gap: 12 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 16, flexWrap: "wrap" }}>
        <div style={{ flexShrink: 0, width: 72, height: 72, borderRadius: 16, background: "var(--amber-dim)", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
          <div style={{ fontWeight: 800, fontSize: daysLeft <= 0 ? 15 : 26, color: "var(--amber)", lineHeight: 1 }}>{daysLeft > 0 ? daysLeft : "0"}</div>
          <div className="mono" style={{ fontSize: 9.5, color: "var(--amber-2)", marginTop: 2 }}>{dayLabel}</div>
        </div>
        <div style={{ flex: 1, minWidth: 200 }}>
          <div className="eyebrow" style={{ color: "var(--amber)", marginBottom: 4 }}>Next exam · {course ? course.name : next.courseId}{next.label ? ` (${next.label})` : ""}</div>
          <div style={{ fontSize: 14.5, color: "var(--text)", fontWeight: 600, lineHeight: 1.4 }}>
            {course ? course.code : ""} · {dateLabel} · {next.time}{next.venue && next.venue !== "TBD" ? ` · ${next.venue}` : ""}
          </div>
        </div>
      </div>
      {tip && (
        <div style={{ fontSize: 13.5, color: "var(--text-2)", lineHeight: 1.55, borderTop: "1px solid var(--line)", paddingTop: 10 }}>
          <strong style={{ color: "var(--text)" }}>Tip: </strong>{tip}
        </div>
      )}
    </div>
  );
}

